     1	package pousada.domain;
     2	
     3	import pousada.BusinessException;
     4	import pousada.ErrorCode;
     5	import pousada.identity.GuestIdentity;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.util.Arrays;
    10	
    11	import static pousada.domain.ReservationStatus.*;
    12	
    13	/** refund é null enquanto a reserva não for cancelada. */
    14	public record Reservation(
    15	        long id,
    16	        Room room,
    17	        String guestName,
    18	        String guestEmail,
    19	        GuestIdentity identity,
    20	        LocalDate checkIn,
    21	        LocalDate checkOut,
    22	        int guests,
    23	        RatePlan ratePlan,
    24	        Quote quote,
    25	        ReservationStatus status,
    26	        BigDecimal amountPaid,
    27	        BigDecimal refund) {
    28	
    29	    public static Reservation pending(Room room, NewReservation n) {
    30	        Quote quote = Quote.of(room, n.checkIn(), n.checkOut(), n.ratePlan());
    31	        return new Reservation(0, room, n.guestName(), n.guestEmail(), n.identity(), n.checkIn(), n.checkOut(),
    32	                n.guests(), n.ratePlan(), quote, PENDING, Money.ZERO, null);
    33	    }
    34	
    35	    public Reservation withId(long newId) {
    36	        return new Reservation(newId, room, guestName, guestEmail, identity, checkIn, checkOut, guests, ratePlan,
    37	                quote, status, amountPaid, refund);
    38	    }
    39	
    40	    public Reservation confirm() {
    41	        requireStatus("confirmada", PENDING);
    42	        return with(CONFIRMED, quote.total(), refund);
    43	    }
    44	
    45	    public Reservation doCheckIn() {
    46	        requireStatus("com check-in", CONFIRMED);
    47	        return with(CHECKED_IN, amountPaid, refund);
    48	    }
    49	
    50	    public Reservation doCheckOut() {
    51	        requireStatus("com check-out", CHECKED_IN);
    52	        return with(CHECKED_OUT, amountPaid, refund);
    53	    }
    54	
    55	    public Reservation cancel() {
    56	        requireStatus("cancelada", PENDING, CONFIRMED);
    57	        return with(CANCELLED, amountPaid, ratePlan.refundOf(amountPaid));
    58	    }
    59	
    60	    /** O que ficou com a pousada: pago menos devolvido. */
    61	    public BigDecimal retained() {
    62	        return refund == null ? amountPaid : Money.round(amountPaid.subtract(refund));
    63	    }
    64	
    65	    public void requirePaid() {
    66	        if (!status.isPaid()) {
    67	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,
    68	                    "Só existe segunda via de reserva paga; a reserva está " + status);
    69	        }
    70	    }
    71	
    72	    private Reservation with(ReservationStatus newStatus, BigDecimal paid, BigDecimal newRefund) {
    73	        return new Reservation(id, room, guestName, guestEmail, identity, checkIn, checkOut, guests, ratePlan,
    74	                quote, newStatus, paid, newRefund);
    75	    }
    76	
    77	    private void requireStatus(String action, ReservationStatus... allowed) {
    78	        if (!Arrays.asList(allowed).contains(status)) {
    79	            throw new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,
    80	                    "A reserva está " + status + " e não pode ser " + action);
    81	        }
    82	    }
    83	}
