     1	package pousada.identity;
     2	
     3	import pousada.BusinessException;
     4	import pousada.ErrorCode;
     5	
     6	import java.util.ArrayList;
     7	import java.util.LinkedHashMap;
     8	import java.util.List;
     9	import java.util.Map;
    10	import java.util.function.Function;
    11	
    12	/** Todas as formas de identificação aceitas. Uma nova forma entra aqui, com seus campos e sua fábrica. */
    13	public enum IdentityKind {
    14	    CPF(List.of("guestCpf"),
    15	            v -> new CpfIdentity(v.get("guestCpf"))),
    16	    CNPJ(List.of("companyCnpj", "companyName"),
    17	            v -> new CnpjIdentity(v.get("companyCnpj"), v.get("companyName"))),
    18	    PASSPORT(List.of("guestPassport", "guestCountry"),
    19	            v -> new PassportIdentity(v.get("guestPassport"), v.get("guestCountry")));
    20	
    21	    private final List<String> fieldNames;
    22	    private final Function<Map<String, String>, GuestIdentity> factory;
    23	
    24	    IdentityKind(List<String> fieldNames, Function<Map<String, String>, GuestIdentity> factory) {
    25	        this.fieldNames = fieldNames;
    26	        this.factory = factory;
    27	    }
    28	
    29	    public GuestIdentity create(Map<String, String> values) {
    30	        return factory.apply(values);
    31	    }
    32	
    33	    /** Nomes de todos os campos de identificação, na ordem em que aparecem na API. */
    34	    public static List<String> allFieldNames() {
    35	        List<String> names = new ArrayList<>();
    36	        for (IdentityKind kind : values()) {
    37	            names.addAll(kind.fieldNames);
    38	        }
    39	        return names;
    40	    }
    41	
    42	    /** Todos os campos de identificação; os que a identidade não preenche ficam null. */
    43	    public static Map<String, String> fieldsOf(GuestIdentity identity) {
    44	        Map<String, String> all = new LinkedHashMap<>();
    45	        for (String name : allFieldNames()) {
    46	            all.put(name, identity.fields().get(name));
    47	        }
    48	        return all;
    49	    }
    50	
    51	    /**
    52	     * Descobre a forma de identificação a partir dos valores informados (campo ausente, nulo ou em branco
    53	     * conta como não informado). Tem que haver uma, e só uma, forma, com todos os seus campos.
    54	     */
    55	    public static GuestIdentity fromValues(Map<String, String> informed) {
    56	        List<IdentityKind> used = new ArrayList<>();
    57	        for (IdentityKind kind : values()) {
    58	            if (kind.fieldNames.stream().anyMatch(n -> informed.get(n) != null && !informed.get(n).isBlank())) {
    59	                used.add(kind);
    60	            }
    61	        }
    62	        if (used.size() != 1) {
    63	            throw new BusinessException(ErrorCode.INVALID_REQUEST,
    64	                    "Informe uma, e só uma, forma de identificação: guestCpf, companyCnpj + companyName "
    65	                            + "ou guestPassport + guestCountry");
    66	        }
    67	        IdentityKind kind = used.get(0);
    68	        Map<String, String> values = new LinkedHashMap<>();
    69	        for (String name : kind.fieldNames) {
    70	            String value = informed.get(name);
    71	            if (value == null || value.isBlank()) {
    72	                throw new BusinessException(ErrorCode.INVALID_REQUEST, "Campo obrigatório: " + name);
    73	            }
    74	            values.put(name, value);
    75	        }
    76	        return kind.create(values);
    77	    }
