 37	        password = System.getenv("DB_PASSWORD");
 38	        schema = "teste_" + UUID.randomUUID().toString().replace("-", "");
 39	        try (Connection c = DriverManager.getConnection(adminUrl, user, password); Statement s = c.createStatement()) {
 40	            s.execute("CREATE SCHEMA " + schema);
 41	        }
 42	        String sep = adminUrl.contains("?") ? "&" : "?";
 43	        db = new Database(adminUrl + sep + "currentSchema=" + schema, user, password);
 44	        app = App.start(0, db);
 45	    }
 46	
 47	    @AfterAll
 48	    static void stop() throws Exception {
 49	        if (app != null) app.stop();
 50	        if (db != null) db.close();
 51	        if (schema != null) {
 52	            try (Connection c = DriverManager.getConnection(adminUrl, user, password); Statement s = c.createStatement()) {
 53	                s.execute("DROP SCHEMA " + schema + " CASCADE");
 54	            }
 55	        }
